      '小熊猫与大熊猫并非近亲，却各自演化出由腕骨形成、可辅助抓握竹枝的“伪拇指”。',
      '灵活的脚踝能显著转动，使它可以头朝下沿树干下降。',
      '尾长约 37—47.2 厘米，约为头体长的六成到八成。',
      '锈红背毛能融入树冠中的红褐色苔藓、地衣和枯叶背景。',
      '小熊猫会用舌头下方的特殊结构收集液态气味，再送至口腔内的感觉器官分析。',
      '新生幼崽约重 90—110 克，最初数月主要留在母兽铺有苔藓和树叶的巢内。',
